using System;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Security.Principal;
using System.Windows.Forms;
using Microsoft.Win32;

[assembly: AssemblyTitle("GIN-Desktop_v051")]
[assembly: AssemblyDescription("GIN-Desktop_v051 Setup")]
[assembly: AssemblyCompany("VladiMIR+AI")]
[assembly: AssemblyTrademark("VladiMIR+AI")]
[assembly: AssemblyProduct("GIN-Desktop_v051")]
[assembly: AssemblyCopyright("VladiMIR+AI")]
[assembly: AssemblyVersion("0.51.0.0")]
[assembly: AssemblyFileVersion("0.51.0.0")]

namespace GINDesktopInstaller {
    static class Program {
        private static readonly string AppExeB64 = "";
        private static readonly string UninstExeB64 = "";
        private static readonly string IcoB64 = "";

        [STAThread]
        static void Main(string[] args) {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);

            bool isUpdate = false;
            bool isSilent = false;
            string customTargetDir = null;

            if (args != null) {
                foreach (string arg in args) {
                    if (arg.Equals("/update", StringComparison.OrdinalIgnoreCase) ||
                        arg.Equals("-update", StringComparison.OrdinalIgnoreCase) ||
                        arg.Equals("--update", StringComparison.OrdinalIgnoreCase)) {
                        isUpdate = true;
                        isSilent = true;
                    } else if (arg.Equals("/silent", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("-silent", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("--silent", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("/s", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("-s", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("/q", StringComparison.OrdinalIgnoreCase) ||
                               arg.Equals("-q", StringComparison.OrdinalIgnoreCase)) {
                        isSilent = true;
                    } else if (arg.StartsWith("/target:", StringComparison.OrdinalIgnoreCase)) {
                        customTargetDir = arg.Substring(8).Trim(new char[] { '\"', ' ' });
                    } else if (arg.StartsWith("-target:", StringComparison.OrdinalIgnoreCase)) {
                        customTargetDir = arg.Substring(8).Trim(new char[] { '\"', ' ' });
                    }
                }
            }

            if (!IsAdministrator()) {
                try {
                    ProcessStartInfo psi = new ProcessStartInfo {
                        FileName = Application.ExecutablePath,
                        Arguments = (args != null && args.Length > 0) ? string.Join(" ", args) : "",
                        Verb = "runas",
                        UseShellExecute = true
                    };
                    Process.Start(psi);
                    return;
                } catch { }
            }

            try {
                // Stop service if installed
                try {
                    ProcessStartInfo scPsi = new ProcessStartInfo("sc.exe", "stop GIN-Desktop") {
                        CreateNoWindow = true,
                        UseShellExecute = false,
                        WindowStyle = ProcessWindowStyle.Hidden
                    };
                    Process scProc = Process.Start(scPsi);
                    if (scProc != null) scProc.WaitForExit(1000);
                } catch { }

                string[] killList = new string[] { "GIN-Desktop", "GIN-Dock", "GIN-Wallpaper-Calend", "GIN-Wallpaper" };
                foreach (string kname in killList) {
                    try {
                        foreach (Process p in Process.GetProcessesByName(kname)) {
                            try { p.Kill(); p.WaitForExit(1500); } catch { }
                        }
                    } catch { }
                }

                // Purge legacy autostart entries
                try {
                    using (RegistryKey rk = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run", true)) {
                        if (rk != null) {
                            rk.DeleteValue("GIN-Wallpaper", false);
                            rk.DeleteValue("GIN-Wallpaper-Calend", false);
                            rk.DeleteValue("GIN-Dock", false);
                        }
                    }
                } catch { }

                string targetDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "GIN-Desktop");
                if (!Directory.Exists(targetDir)) {
                    Directory.CreateDirectory(targetDir);
                }

                string appPath = Path.Combine(targetDir, "GIN-Desktop.exe");
                string uninstPath = Path.Combine(targetDir, "Uninstall.exe");
                string uninstCmd = Path.Combine(targetDir, "uninstall.cmd");
                string icoPath = Path.Combine(targetDir, "app.ico");

                byte[] appBytes = Convert.FromBase64String(AppExeB64);
                byte[] uninstBytes = Convert.FromBase64String(UninstExeB64);
                byte[] icoBytes = Convert.FromBase64String(IcoB64);

                File.WriteAllBytes(appPath, appBytes);
                File.WriteAllBytes(uninstPath, uninstBytes);
                File.WriteAllBytes(icoPath, icoBytes);

                File.WriteAllText(uninstCmd, "@echo off\r\n\"%~dp0Uninstall.exe\"\r\n");

                // If portable / custom target directory was passed, update it as well
                if (!string.IsNullOrEmpty(customTargetDir) && Directory.Exists(customTargetDir) && !customTargetDir.Equals(targetDir, StringComparison.OrdinalIgnoreCase)) {
                    try {
                        File.WriteAllBytes(Path.Combine(customTargetDir, "GIN-Desktop.exe"), appBytes);
                        File.WriteAllBytes(Path.Combine(customTargetDir, "Uninstall.exe"), uninstBytes);
                        File.WriteAllBytes(Path.Combine(customTargetDir, "app.ico"), icoBytes);
                    } catch { }
                }

                // NEVER recreate or duplicate desktop shortcuts during automated update
                if (!isUpdate) {
                    string desktop = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
                    foreach (string f in Directory.GetFiles(desktop, "*GIN*Dock*.lnk")) {
                        try { File.Delete(f); } catch { }
                    }
                    foreach (string f in Directory.GetFiles(desktop, "*GIN*Wallpaper*.lnk")) {
                        try { File.Delete(f); } catch { }
                    }
                    string lnkPath = Path.Combine(desktop, "GIN Desktop.lnk");
                    CreateShortcut(lnkPath, appPath, targetDir, "GIN Desktop v051", icoPath);
                }

                // Clean up any legacy Start Menu folder if present (user explicitly requested single shortcut in Start Menu root)
                string programsDir = Environment.GetFolderPath(Environment.SpecialFolder.Programs);
                string oldStartMenuDir = Path.Combine(programsDir, "GIN Desktop");
                if (Directory.Exists(oldStartMenuDir)) {
                    try { Directory.Delete(oldStartMenuDir, true); } catch { }
                }
                string oldLegacyDir = Path.Combine(programsDir, "GIN Dock Wallpaper");
                if (Directory.Exists(oldLegacyDir)) {
                    try { Directory.Delete(oldLegacyDir, true); } catch { }
                }

                // Place strictly ONE clean shortcut directly in Start Menu Programs root: "GIN Desktop.lnk"
                string startMenuLnk = Path.Combine(programsDir, "GIN Desktop.lnk");
                CreateShortcut(startMenuLnk, appPath, targetDir, "GIN Desktop", icoPath);

                try {
                    RegistryKey parentKey = IsAdministrator() ? Registry.LocalMachine : Registry.CurrentUser;
                    try { parentKey.DeleteSubKeyTree(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\GIN-Desktop", false); } catch { }
                    using (RegistryKey unKey = parentKey.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall\GIN-Desktop")) {
                        if (unKey != null) {
                            unKey.SetValue("DisplayName", "GIN Desktop v051");
                            unKey.SetValue("DisplayIcon", icoPath);
                            unKey.SetValue("DisplayVersion", "v051");
                            unKey.SetValue("Publisher", "VladiMIR+AI (Vladimir Bulantsev)");
                            unKey.SetValue("UninstallString", "\"" + uninstPath + "\"");
                            unKey.SetValue("InstallLocation", targetDir);
                            unKey.SetValue("URLInfoAbout", "https://github.com/GinCz/Windows_scripts/tree/main/GIN-Desktop");
                        }
                    }
                } catch { }

                string execToStart = (!string.IsNullOrEmpty(customTargetDir) && File.Exists(Path.Combine(customTargetDir, "GIN-Desktop.exe")))
                    ? Path.Combine(customTargetDir, "GIN-Desktop.exe")
                    : appPath;
                string workingToStart = Path.GetDirectoryName(execToStart);

                Process.Start(new ProcessStartInfo {
                    FileName = execToStart,
                    WorkingDirectory = workingToStart,
                    Arguments = isUpdate ? "--updated" : "",
                    UseShellExecute = true
                });

                if (!isSilent) {
                    MessageBox.Show(
                        "⚡ GIN Desktop v051 has been successfully installed!\n\n" +
                        "• Running in System Tray (sand G icon).\n" +
                        "• Dock Bar: Auto-hiding at Top, hover top-left corner to activate.\n" +
                        "• Dynamic 4K Wallpaper & Calendar HUD with midnight 00:03 auto-sync.\n" +
                        "• Hardware HUD: CPU, RAM, GPU %, and Temperature monitoring.\n" +
                        "• Weather HUD: Real-time weather badge directly under calendar.\n" +
                        "• Silent background updates with tray HUD notifications & gentle sounds.\n" +
                        "• Portable configuration: zero registry clutter.",
                        "GIN Desktop Setup",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information
                    );
                }
            } catch (Exception ex) {
                if (!isSilent) {
                    MessageBox.Show("Installation failed:\n" + ex.Message, "Setup Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }
        }

        private static bool IsAdministrator() {
            try {
                WindowsIdentity id = WindowsIdentity.GetCurrent();
                WindowsPrincipal principal = new WindowsPrincipal(id);
                return principal.IsInRole(WindowsBuiltInRole.Administrator);
            } catch {
                return false;
            }
        }

        private static void CreateShortcut(string shortcutPath, string targetPath, string workingDir, string description, string iconPath) {
            try {
                Type t = Type.GetTypeFromProgID("WScript.Shell");
                dynamic shell = Activator.CreateInstance(t);
                dynamic shortcut = shell.CreateShortcut(shortcutPath);
                shortcut.TargetPath = targetPath;
                shortcut.WorkingDirectory = workingDir;
                shortcut.Description = description;
                if (!string.IsNullOrEmpty(iconPath) && File.Exists(iconPath)) {
                    shortcut.IconLocation = iconPath + ",0";
                }
                shortcut.Save();
            } catch { }
        }
    }
}
